import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import LoadingSpinner from '../common/LoadingSpinner';
import { validateRegisterForm, getErrorMessage } from '../../utils/helpers';
import { SUCCESS_MESSAGES } from '../../utils/constants';

const Register = () => {
  const [formData, setFormData] = useState({
    username: '',
    email: '',
    password: '',
    confirmPassword: ''
  });
  const [errors, setErrors] = useState({});
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState('');
  const [isSuccess, setIsSuccess] = useState(false);
  const [debugInfo, setDebugInfo] = useState(null);

  const { register } = useAuth();
  const navigate = useNavigate();

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));

    // Clear field error when user starts typing
    if (errors[name]) {
      setErrors(prev => ({
        ...prev,
        [name]: ''
      }));
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    // Validate form
    const validationErrors = validateRegisterForm(formData);
    if (Object.keys(validationErrors).length > 0) {
      setErrors(validationErrors);
      return;
    }

    setLoading(true);
    setMessage('');
    setErrors({});
    setDebugInfo(null);

    try {
      const registerData = {
        username: formData.username,
        email: formData.email,
        password: formData.password
      };

      console.log('Attempting to register with:', registerData);
      const response = await register(registerData);
      
      // Log the response for debugging
      console.log('Registration response:', response);
      setDebugInfo({
        status: response.status,
        data: response.data,
        headers: response.headers
      });
      
      setMessage(SUCCESS_MESSAGES.REGISTER_SUCCESS);
      setIsSuccess(true);
      
      // Redirect to login after a delay
      setTimeout(() => {
        navigate('/login');
      }, 5000); // Increased time to read debug info

    } catch (error) {
      console.error('Registration error:', error);
      const errorMessage = getErrorMessage(error);
      setErrors({ general: errorMessage });
      
      // Debug information
      setDebugInfo({
        error: error.message,
        status: error.response?.status,
        data: error.response?.data,
        config: {
          url: error.config?.url,
          method: error.config?.method
        }
      });
    } finally {
      setLoading(false);
    }
  };

  const testEmailService = async () => {
    try {
      setLoading(true);
      // This would be a test endpoint in your backend
      console.log('Testing email service...');
      setMessage('Email service test - check backend logs');
    } catch (error) {
      console.error('Email test error:', error);
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return <LoadingSpinner message="Creating your account..." />;
  }

  if (isSuccess) {
    return (
      <div className="auth-container">
        <div className="auth-card">
          <div className="success-content">
            <h2>Registration Successful!</h2>
            <p>{message}</p>
            
            {/* Debug Information */}
            {debugInfo && process.env.NODE_ENV === 'development' && (
              <div className="debug-info" style={{
                background: '#f8f9fa',
                padding: '15px',
                margin: '20px 0',
                borderRadius: '4px',
                border: '1px solid #dee2e6',
                fontSize: '12px'
              }}>
                <h4>Debug Information:</h4>
                <pre style={{ whiteSpace: 'pre-wrap', fontSize: '11px' }}>
                  {JSON.stringify(debugInfo, null, 2)}
                </pre>
              </div>
            )}
            
            <div className="verification-instructions">
              <h3>Next Steps:</h3>
              <ol>
                <li>Check your email inbox for a verification link</li>
                <li>Check your spam/junk folder if you don't see it</li>
                <li>Click the verification link to activate your account</li>
                <li>Then return here to login</li>
              </ol>
            </div>
            
            <div className="auth-actions">
              <Link to="/login" className="btn btn-primary">Go to Login</Link>
              <button 
                onClick={() => setIsSuccess(false)} 
                className="btn btn-outline"
              >
                Register Another Account
              </button>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="auth-container">
      <div className="auth-card">
        <div className="auth-header">
          <h2>Register as Food Truck Vendor</h2>
          <p>Join our platform and start serving customers</p>
        </div>

        {errors.general && <div className="error-message">{errors.general}</div>}
        
        {/* Debug Information */}
        {debugInfo && process.env.NODE_ENV === 'development' && (
          <div className="debug-info" style={{
            background: '#fff3cd',
            padding: '15px',
            margin: '20px 0',
            borderRadius: '4px',
            border: '1px solid #ffeaa7',
            fontSize: '12px'
          }}>
            <h4>Debug Information:</h4>
            <pre style={{ whiteSpace: 'pre-wrap', fontSize: '11px' }}>
              {JSON.stringify(debugInfo, null, 2)}
            </pre>
          </div>
        )}

        <form onSubmit={handleSubmit} className="auth-form">
          <div className="form-group">
            <label htmlFor="username">Username</label>
            <input
              type="text"
              id="username"
              name="username"
              value={formData.username}
              onChange={handleChange}
              className={errors.username ? 'error' : ''}
              placeholder="Choose a unique username"
            />
            {errors.username && <span className="error-text">{errors.username}</span>}
          </div>

          <div className="form-group">
            <label htmlFor="email">Email</label>
            <input
              type="email"
              id="email"
              name="email"
              value={formData.email}
              onChange={handleChange}
              className={errors.email ? 'error' : ''}
              placeholder="Enter your email address"
            />
            {errors.email && <span className="error-text">{errors.email}</span>}
          </div>

          <div className="form-group">
            <label htmlFor="password">Password</label>
            <input
              type="password"
              id="password"
              name="password"
              value={formData.password}
              onChange={handleChange}
              className={errors.password ? 'error' : ''}
              placeholder="Create a strong password (min 8 characters)"
            />
            {errors.password && <span className="error-text">{errors.password}</span>}
          </div>

          <div className="form-group">
            <label htmlFor="confirmPassword">Confirm Password</label>
            <input
              type="password"
              id="confirmPassword"
              name="confirmPassword"
              value={formData.confirmPassword}
              onChange={handleChange}
              className={errors.confirmPassword ? 'error' : ''}
              placeholder="Confirm your password"
            />
            {errors.confirmPassword && <span className="error-text">{errors.confirmPassword}</span>}
          </div>

          <button type="submit" className="btn btn-primary" disabled={loading}>
            {loading ? 'Creating Account...' : 'Register'}
          </button>
          
          {process.env.NODE_ENV === 'development' && (
            <button 
              type="button" 
              onClick={testEmailService} 
              className="btn btn-outline"
              style={{ marginTop: '10px' }}
            >
              Test Email Service
            </button>
          )}
        </form>

        <div className="auth-footer">
          <p>
            Already have an account? 
            <Link to="/login"> Login here</Link>
          </p>
        </div>
      </div>
    </div>
  );
};

export default Register;
